import json, os, urllib.request
url='http://127.0.0.1:35263/mcp'
headers={'Authorization': 'Bearer '+os.environ['QUEUE_TOKEN'], 'Content-Type':'application/json','MCP-Protocol-Version':'2025-11-25'}
for i,(name,args) in enumerate([('mo-overview',{}),('mo-state',{}),('stats',{})],1):
    data={'jsonrpc':'2.0','id':i,'method':'tools/call','params':{'name':name,'arguments':args}}
    with urllib.request.urlopen(urllib.request.Request(url,json.dumps(data).encode(),headers), timeout=25) as r:
        result=json.load(r)
    if name=='mo-state':
        with open('/tmp/task-queue-before-state.json','w') as f: json.dump(result,f)
        os.chmod('/tmp/task-queue-before-state.json',0o600)
    print(json.dumps({'name':name,'reply':result}))
PY"

